"""Build a PDF from saved experiment evidence; never invent missing results."""
import argparse, json, html, textwrap
from pathlib import Path
from reportlab.lib import colors
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.lib.enums import TA_CENTER
from reportlab.lib.units import cm
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle, Image, PageBreak, Preformatted, KeepTogether
from PIL import Image as PILImage
ROOT=Path(__file__).resolve().parents[1]
T1=ROOT/'outputs'/'task1'; T2=ROOT/'outputs'/'task2'
STYLE=getSampleStyleSheet()
STYLE.add(ParagraphStyle(name='Body2',fontName='Times-Roman',fontSize=11,leading=15,spaceAfter=9))
STYLE.add(ParagraphStyle(name='Caption2',fontName='Times-Italic',fontSize=9,leading=12,spaceAfter=8,alignment=TA_CENTER))
STYLE.add(ParagraphStyle(name='Code2',fontName='Courier',fontSize=6.7,leading=8.2))
STYLE['Heading1'].fontName='Times-Bold'; STYLE['Heading1'].fontSize=20; STYLE['Heading1'].leading=24
STYLE['Heading2'].fontName='Times-Bold'; STYLE['Heading2'].fontSize=14


def build(repo='',model_link='',include_code=False,student='',student_id=''):
    t=json.loads((T1/'results.json').read_text()); m=json.loads((T2/'metrics.json').read_text()) if (T2/'metrics.json').exists() else None
    final=bool(m and repo and model_link and include_code and t['calibration_source']=='User photographs' and t['image_source']!='Synthetic fruit illustration' and t['second_source']!='Synthetic affine transformation of input')
    path=ROOT/'report'/('FCVG101_Report.pdf' if final else 'FCVG101_Report_Draft.pdf')
    s=[]
    def p(x): s.append(Paragraph(x,STYLE['Body2']))
    def h(x): s.append(Paragraph(x,STYLE['Heading1']))
    def sub(x): s.append(Paragraph(x,STYLE['Heading2']))
    def page(): s.append(PageBreak())
    def table(rows,widths):
        data=[[Paragraph(html.escape(str(v)),STYLE['Body2']) for v in row] for row in rows]
        obj=Table(data,colWidths=[w*cm for w in widths],repeatRows=1,hAlign='LEFT'); obj.setStyle(TableStyle([('GRID',(0,0),(-1,-1),.5,colors.grey),('BACKGROUND',(0,0),(-1,0),colors.whitesmoke),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),6),('RIGHTPADDING',(0,0),(-1,-1),6)]));s.append(obj);s.append(Spacer(1,8))
    def fig(path,caption,w=16,hmax=10):
        if not path.exists(): return
        with PILImage.open(path) as im: iw,ih=im.size
        scale=min(w*cm/iw,hmax*cm/ih); s.append(Image(str(path),width=iw*scale,height=ih*scale));s.append(Paragraph(caption,STYLE['Caption2']))
    def link(url): return f'<link href="{html.escape(url,quote=True)}" color="blue">{html.escape(url)}</link>'
    s.append(Spacer(1,1.5*cm));h('FCVG101 | Introduction to Computer Vision')
    h('An Intelligent Fruit Quality Inspection System Using Computer Vision and Deep Learning')
    p('<b>Project:</b> Smart Organic Farm Assistant');p('<b>Student name:</b> '+html.escape(student or '[Enter your name]'));p('<b>Student ID:</b> '+html.escape(student_id or '[Enter your student ID]'));p('<b>Version:</b> '+('Report with recorded evidence' if final else 'Working report / experiment template — not ready for submission'))
    sub('Abstract');p('This project develops a visual inspection prototype for an organic farm. The system combines camera geometry, traditional image processing and binary fruit-quality classification with a Streamlit interface. Classical processing includes denoising, image gradients, frequency analysis, interest point detection and feature matching. A compact CNN is designed to distinguish fresh and rotten fruit using labelled images. The report records reproducible measured outputs where available and identifies missing physical-camera and learning evidence. The prototype supports visual inspection; it cannot determine microbiological safety.')
    sub('Contents');p('1. Problem definition and scope<br/>2. Task 1: Image analysis and camera geometry<br/>3. Task 2: Dataset, learning pipeline and evaluation<br/>4. Task 3: Application integration<br/>5. Evaluation, limitations and conclusion<br/>6. Repository, references and submission checks')
    page();h('1. Problem definition and scope');p('Farm operators need a repeatable way to screen fruit for visible defects. The proposed MVP accepts uploaded images and provides classical analysis or a fresh/rotten prediction. A human operator retains responsibility for the final decision. The design deliberately avoids estimating depth or physical dimensions without an appropriate measurement setup. Binary classification is the selected prediction task.')
    sub('System architecture');table([['Layer','Implementation','Output'],['Image input','Pillow / OpenCV','RGB or BGR image'],['Classical vision','src/vision.py','Filters, edges, Fourier outputs, features and camera calibration'],['Learning','src/model.py and src/train.py','CNN checkpoint and evaluation metrics'],['Interface','app.py / Streamlit','Selected task, visual evidence, probabilities']],[3,6,7])
    sub('Coursework alignment');table([['Criterion','Evidence'],['Task 1 (20)','Calibration, K and distortion, filtering PSNR, feature matching and code modules.'],['Task 2 (35)','Cleaning, split, augmentation, CNN, evaluation plots and model artifact generation.'],['Task 3 (30)','Mode selection and shared modules; manual browser validation required.'],['Documentation (15)','Report, README, reproducibility instructions, repository and artifact links.']],[4,12]);p('The brief requires a PDF under 5 MB with selectable Python source, generated figures and numerical results. Repository and model links supplement the source appendix; they do not replace that stated requirement unless the instructor approves.')
    page();h('2. Task 1 — Camera geometry');p('The ideal pinhole relation maps a 3D point (X, Y, Z) to pixel coordinates u = fx X/Z + cx and v = fy Y/Z + cy. The intrinsic matrix K contains focal lengths fx and fy, the principal point (cx, cy), and a final homogeneous row [0, 0, 1]. Lens distortion deviates from this ideal projection. Calibration uses known planar checkerboard corner positions, detected image points and OpenCV least-squares optimisation.')
    c=t['calibration'];p(f"<b>Evidence source:</b> {html.escape(t['calibration_source'])}. {len(c['accepted'])} accepted views; resolution {c['size'][0]} × {c['size'][1]} pixels. RMS reprojection error: {c['rms_px']:.4f} pixels.")
    table([['Intrinsic matrix K (estimated)','','']]+[[f'{x:.4f}' for x in row] for row in c['K']],[5.33,5.33,5.34]);p('Distortion (k1, k2, p1, p2, k3): '+', '.join(f'{x:.5f}' for x in c['distortion']))
    if t['known_K'] is not None:p('The simulated camera was defined with fx = 780, fy = 770, cx = 400 and cy = 300. Agreement of estimated intrinsics with these reference values checks the implementation, not real hardware. Higher-order distortion terms can be poorly constrained by limited board coverage.')
    fig(T1/'calibration.jpg','Figure 1. Detected corners, distorted input and corrected view.',hmax=5.7)
    p('For physical validation, photograph a printed 10 × 7 square checkerboard from diverse angles using one camera at one resolution. Measure the actual square width and supply those images to the experiment script. Record new intrinsics and reprojection errors; do not reuse simulated K for a physical camera.')
    page();h('2.1 Filtering and gradients');p('A controlled salt-and-pepper noise experiment compares a 5 × 5 box average, a Gaussian-weighted average and a nonlinear median filter. The box and Gaussian operators smooth local intensity variation; the median rejects extreme outliers while preserving sharper boundaries. PSNR is calculated against the original input in dB; higher values indicate lower pixel reconstruction error for this specific experiment.')
    p('<b>Input:</b> '+html.escape(t['image_source']));fig(T1/'filtering.jpg','Figure 2. Input, deliberately corrupted image and filter outputs.',hmax=10)
    table([['Method','Measured PSNR (dB)']]+[[k,f'{v:.2f}'] for k,v in t['psnr_db'].items()],[8,8]);best=max((k for k in t['psnr_db'] if k!='Noisy'),key=t['psnr_db'].get);p(f'{best} gives the highest PSNR on this controlled input. This does not establish universal superiority for other noise types or real fruit photographs.')
    page();h('2.2 Edges and frequency-domain processing');p('Sobel estimates horizontal and vertical intensity derivatives; their magnitude emphasises rapid intensity changes. Canny uses smoothing, gradient analysis, non-maximum suppression and hysteresis to produce thin edges. The fixed thresholds are suitable for a demonstration but need testing under changes in lighting.')
    fig(T1/'edges.jpg','Figure 3. Sobel magnitude and Canny edge map.',hmax=6.0)
    p('A two-dimensional discrete Fourier transform represents spatial intensity variation by frequency. The shifted log-magnitude spectrum displays low frequencies near the centre. A circular mask retains low frequencies for smoothing, while the complementary mask emphasises fine structure and edges. A hard cutoff can cause ringing.')
    fig(T1/'frequency.jpg','Figure 4. Log spectrum, inverse low-pass result and high-pass magnitude.',hmax=5.8)
    fig(T1/'psnr.png','Figure 5. Measured denoising PSNR, same controlled input.',hmax=5.0)
    page();h('2.3 Features and cross-view matching');p('Harris corners measure local gradient variation in two directions. SIFT describes scale-space interest points using local gradient patterns; ORB combines oriented FAST keypoints with binary descriptors. The matching engine compares nearest and second-nearest descriptor distances and accepts a candidate when d1/d2 is below 0.75. RANSAC estimates a homography as a geometric consistency check. Only the first 50 matches are drawn for readability.')
    fig(T1/'features.jpg','Figure 6. Harris, SIFT and ORB detections.',hmax=5.5)
    table([['Detector','Detected on first image']]+[[k,v] for k,v in t['feature_counts'].items()],[8,8]);p('<b>Second view:</b> '+html.escape(t['second_source']));table([['Method','Ratio matches','RANSAC inliers']]+[[k,v['ratio_matches'],v['ransac_inliers']] for k,v in t['matches'].items()],[5,5.5,5.5]);fig(T1/'sift_matches.jpg','Figure 7. SIFT descriptor matches across the two inputs.',hmax=4.7);p('The simulated affine view is a controlled test and may be easier than independently captured photos with occlusion or perspective changes.')
    page();h('3. Task 2 — Data pipeline and CNN');p('The selected dataset is Sultana, Jahan and Uddin (2022), containing original images across eight fruit types. The raw subset is reported to contain 3,200 images (1,600 fresh and 1,600 rotten). The pre-augmented subset is intentionally excluded to reduce the risk of variants of the same original crossing data splits.')
    p('Source: '+link('https://data.mendeley.com/datasets/bdd69gyhv8/1')+'<br/>Download mirror: '+link('https://huggingface.co/datasets/Project-AgML/fresh_rotten_fruit_classification'))
    sub('Pipeline');table([['Step','Design decision'],['Ingest','Download raw subset, decode RGB, save manifest and images.'],['Clean','Reject unreadable images, invalid labels and exact decoded-pixel duplicates.'],['Split','70% train, 15% validation, 15% test; stratify by quality and fruit type.'],['Augment','Training only: horizontal flip, rotation and brightness change.'],['Transform','Resize to 128 × 128, scale to [0,1], normalize to [-1,1].'],['Evaluate','Choose best validation accuracy; evaluate held-out test once.']],[3.2,12.8]);p('Exact duplicate removal does not detect every near-duplicate or images from the same fruit specimen. The source lacks a verified specimen ID in the selected schema; group-wise validation and external farm photographs are future improvements.')
    sub('Model configuration');p('Four convolutional stages (16, 32, 64, 128 channels), ReLU activations, batch normalization in the first three stages, max pooling and adaptive average pooling produce a compact representation. A fully connected 64-unit layer and dropout (0.3) precede two output logits. Adam minimises cross-entropy loss. Default settings: 12 epochs, batch size 32, learning rate 0.001, seed 42. Inference uses softmax with identical deterministic normalization.')
    page();h('3.1 Evaluation and results');
    if m:
        p('Recorded learning results from the local run: '+html.escape(str(m['source']))+'.');table([['Metric','Value'],['Valid images',m['cleaning']['valid']],['Invalid images',m['cleaning']['invalid']],['Exact duplicates',m['cleaning']['exact_duplicates']],['Best epoch',m['best_epoch']],['Held-out test accuracy',f"{m['test_accuracy']:.2%}"],['Held-out macro F1',f"{m['test_macro_f1']:.4f}"],['Test loss',f"{m['test_loss']:.4f}"]],[8,8]);fig(T2/'class_distribution.png','Figure 8. Class counts by split.',hmax=5);fig(T2/'confusion_matrix.png','Figure 9. Held-out confusion matrix.',hmax=6);page();h('3.2 Training diagnostics');fig(T2/'accuracy.png','Figure 10. Training and validation accuracy.',hmax=6);fig(T2/'loss.png','Figure 11. Training and validation loss.',hmax=6);fig(T2/'dataset_examples.jpg','Figure 12. Held-out examples.',hmax=7);p('Interpret the observed train-validation gap, failure cases and class-specific recall. Record a specific explanation using the actual output and independently inspected misclassifications.')
    else:
        p('<b>Not measured:</b> the public fruit dataset was not downloaded in the current environment, so no trained checkpoint, test accuracy, F1 score, confusion matrix or learning curves are claimed. The code creates these artifacts from a real training run.');table([['Evidence required','Generated file after training'],['Dataset counts','outputs/task2/class_distribution.png'],['Dataset examples','outputs/task2/dataset_examples.jpg'],['Training and validation accuracy','outputs/task2/accuracy.png'],['Training and validation loss','outputs/task2/loss.png'],['Confusion matrix','outputs/task2/confusion_matrix.png'],['Accuracy, F1, per-class metrics','outputs/task2/metrics.json'],['Trained model','models/fruit_cnn.pt']],[7,9]);p('Run the download and training commands in README.md, then rebuild the report. Replace this provisional evidence with the measured results. Accuracy is the fraction of correct predictions; macro F1 gives equal weight to both class F1 scores. The confusion matrix exposes false fresh and false rotten predictions.')
    page();h('4. Task 3 — Application integration');p('The Streamlit interface routes the operator’s selected mode to an explicit function. This is deterministic intent selection rather than an unverified natural-language agent. The same CNN architecture and transform are imported for deployment. Model loading is cached, and a missing checkpoint triggers a message rather than a random prediction.')
    table([['Mode','Input / result'],['Classify fruit','One image; class and softmax confidence.'],['Filter and edges','One image; box, Gaussian, median, Sobel, Canny.'],['Frequency analysis','One image; spectrum and low/high-pass outputs.'],['Detect features','One image; Harris, SIFT, ORB and counts.'],['Match two views','Two images; ratio-test matches and inlier counts.'],['Calibrate camera','At least five checkerboard photographs; K, distortion, RMS.'],['Undistort','Image from calibrated camera, same resolution; corrected image.']],[5.5,10.5]);sub('Manual acceptance checks');p('Launch Streamlit locally. Upload a valid fruit photograph and verify the original and processed outputs. Select each mode, test missing files, incompatible resolutions and an absent model. After training, check that class probabilities sum to one and compare several known labels. Capture screenshots of each successful workflow for final evidence. Browser execution was not verified in the current environment.')
    screenshots=sorted(f for f in (ROOT/'report'/'screenshots').glob('*') if f.suffix.lower() in {'.jpg','.jpeg','.png'})
    for i,shot in enumerate(screenshots):
        page();h('4.1 Application demonstration');fig(shot,'Application evidence '+str(i+1)+': '+html.escape(shot.stem),hmax=17)
    page();h('5. Evaluation, limitations and conclusion');p('The recorded classical-vision experiment demonstrates that the image analysis functions execute and produce quantitative evidence on controlled inputs. The supplied unit tests exercise pinhole projection, classical operations and CNN output shape/probability normalisation. These are smoke tests; they are not proof of model accuracy or field reliability.')
    p('The model may rely on background, lighting, fruit type or camera-specific correlations. Shadows and natural colour variation can resemble deterioration. Camera calibration depends on stable intrinsics, known checkerboard size and adequate views. A confidence score reflects the network output, not a calibrated guarantee of quality. The system should be used only as a visual screening aid alongside human inspection.')
    sub('Reproducibility');p('From the project root, install requirements, execute the classical experiment, fetch the raw dataset and train. Run the application in a browser. Rebuild the report with the measured outputs and the actual repository and model links. The README provides exact commands and a rubric evidence checklist.')
    sub('Conclusion');p('The MVP architecture connects foundational computer vision and a deployable deep-learning design. The recorded controlled classical tests provide a baseline for validating each module. Physical-camera evidence, held-out fruit classification results and a browser demonstration are required to substantiate the final system performance.' if not final else 'The recorded experiments support the implemented prototype under the tested conditions. The system remains a visual aid and requires additional external validation before operational use.')
    page();h('6. Repository, references and submission checks');p('<b>Code repository:</b> '+(link(repo) if repo else '[Add the actual GitHub repository URL after publishing.]'));p('<b>Trained model:</b> '+(link(model_link) if model_link else '[Add a real shareable model URL after training and uploading.]'))
    for f in ['src/vision.py','src/experiment.py','src/download_data.py','src/model.py','src/train.py','app.py','tests/test_core.py']:
        p(html.escape(f)+(' — '+link(repo.rstrip('/')+'/blob/main/'+f) if repo else ' — local project file; GitHub link pending.'))
    sub('References');p('Sultana, N., Jahan, M. and Uddin, M. S. (2022). Fresh and Rotten Fruits Dataset for Machine-Based Evaluation of Fruit Quality. Mendeley Data, v1. '+link('https://doi.org/10.17632/bdd69gyhv8.1')+'. CC BY 4.0.');p('Sultana et al. (2022). An extensive dataset for successful recognition of fresh and rotten fruits. Data in Brief, 44, 108552. '+link('https://doi.org/10.1016/j.dib.2022.108552')+'.');p('OpenCV documentation: '+link('https://docs.opencv.org/4.x/')+'<br/>PyTorch documentation: '+link('https://pytorch.org/docs/stable/')+'<br/>Streamlit documentation: '+link('https://docs.streamlit.io/'))
    p('<b>Before submission:</b> enter student details; verify citations and permitted AI assistance; replace simulated evidence with camera/fruit photographs where required; train and verify the model; insert actual screenshots; confirm repository access and model link; include selectable source appendix unless instructor authorizes links alone; check the PDF is below 5 MB.')
    if include_code:
        for f in ['src/vision.py','src/experiment.py','src/download_data.py','src/model.py','src/train.py','app.py','tests/test_core.py']:
            page();h('Appendix — '+f)
            lines=[]
            for line in (ROOT/f).read_text().splitlines(): lines.extend(textwrap.wrap(line,width=110,replace_whitespace=False,drop_whitespace=False,subsequent_indent='    ') or [''])
            s.append(Preformatted('\n'.join(lines),STYLE['Code2']))
    doc=SimpleDocTemplate(str(path),pagesize=(21*cm,29.7*cm),rightMargin=2.2*cm,leftMargin=2.2*cm,topMargin=1.9*cm,bottomMargin=1.9*cm,title='FCVG101 Fruit Quality Inspection',author='Student project working report')
    doc.build(s);print(path, path.stat().st_size,'bytes');return path

if __name__=='__main__':
    a=argparse.ArgumentParser();a.add_argument('--repo',default='');a.add_argument('--model-link',default='');a.add_argument('--include-code',action='store_true');a.add_argument('--student',default='');a.add_argument('--student-id',default='');args=a.parse_args();build(args.repo,args.model_link,args.include_code,args.student,args.student_id)
